INSERT INTO `messages` VALUES ('02877520-98c4-4207-8cc9-26b07f53942d','b71f02e1-188e-41b9-9825-1f69137a37d4',NULL,'je souhaite passer dans votre magasin. donne-moi votre adresse','user','2026-04-17 16:28:06','2026-04-17 16:28:06',NULL),('3f502b18-387a-4e46-aa4a-70803824dbe6','b71f02e1-188e-41b9-9825-1f69137a37d4',NULL,'Chez Dr. Maxis Literie, nous sommes présents dans plusieurs endroits sur l\'île de La Réunion. Vous pouvez nous trouver dans les magasins de Saint-Pierre, Saint-André et Saint-Denis. \n\nSaint-Pierre : 19 Chemin château d\'eau, local 1, Rez-de-chaussée, 97410 Saint-Pierre.\nSaint-André : Résidence les Cocotiers, 11 bis Zone de la Cocoteraie, Saint-André.\nSaint-Denis : 07 Rue Lislet Geoffroy, 97490 Saint-Denis, face à l\'Espace Déco.\n\nN\'hésitez pas à vous rendre dans l\'un de nos magasins pour en savoir plus sur nos produits et bénéficier de conseils d\'experts.','bot','2026-04-17 16:28:23','2026-04-17 16:28:23','[]');
